{
"evidence": "النص يصف مودلاً ينتج معلومات تبدو صحيحة ومقنعة لكنها في الحقيقة مختلقة وغير مدعومة بمصدر، وهو ما يطابق تماماً تعريف 'هلوسة' في المصطلحات المرشحة (معلومات تبدو معقولة لكنها خاطئة أو غير مدعومة بالأدلة).",
"choice": "C1",
"rewrite": "يُظهر المودل أحياناً معلومات تبدو صحيحة ومقنعة، لكنها في الواقع خاطئة أو مصطنعة ولا تستند إلى أي مصدر موثوق."
}

{
"evidence": "النص يصف نموذجًا يحقق أداءً ممتازًا على بيانات التدريب لكنه يفشل في التعميم على البيانات الجديدة، وهو ما يتطابق مع تعريف 'فرط التخصيص' الذي يشير إلى مشكلة في التعلّم الآلي حيث يطابق النموذج بيانات التدريب بصورة كبيرة فيفشل في التعميم.",
"choice": "C1",
"rewrite": "أظهر النموذج أداءً استثنائيًا على البيانات التي تم تدريبه عليها، إلا أن أدائه يتدهور بشكل ملحوظ عند تطبيقه على بيانات جديدة."
}

{
"evidence": "النص يصف كيانًا (برنامج) قادرًا على 'إدراك بيئته' (ما يحدث حوله)، والعمل 'بتحكم ذاتي' (يختار خطوات وينفذها بنفسه) لتحقيق 'هدف' محدد، وهو ما يطابق تعريف الوكيل ككيان برمجي يمكنه الإدراك والعمل بتحكم ذاتي لتحقيق هدف.",
"choice": "C1",
"rewrite": "يعمل البرنامج كوكيل برمجي قادر على إدراك بيئته، حيث يتخذ خطواته بنفسه لتنفيذ المهام وصولاً إلى الهدف المحدد."
}

{
"evidence": "النص يذكر تمرير 'مجموعة البيانات كاملة' على 'النموذج' خمس مرات متتالية، وهو ما يطابق تعريف 'دورة' كعملية تدريب كاملة على مجموعة البيانات بأكملها.",
"choice": "C1",
"rewrite": "تم تمرير مجموعة البيانات كاملة على النموذج خمس مرات متتالية خلال عملية الضبط."
}

{
"evidence": "النص يصف المدخلات المقدمة للنموذج في البداية لتحديد المهمة وطريقة الرد، وهو ما يتطابق مع تعريف 'أمر' كمدخلات لتوجيه مخرجات النموذج.",
"choice": "C1",
"rewrite": "تُعدّ الأوامر المدخلة في البداية للنموذج هي التي تحدد له المهمة المطلوبة وطريقة الرد المتوقعة."
}

{
"evidence": "النص يصف إرسال 'قيمة عددية موجبة أو سالبة' من البيئة بعد 'فعل'، وهو ما يتطابق مع تعريف 'المكافأة' كـ 'نتيجة عددية... تحددها البيئة عند القيام بفعل'.",
"choice": "C1",
"rewrite": "بعد تنفيذ أي فعل، ترسل البيئة للوكيل قيمة رقمية (سواء كانت موجبة أو سالبة) تعكس جودة هذا الفعل."
}

{
"evidence": "النص يصف آلية تحديد احتمالات اختيار الأفعال بناءً على الحالة، وهو ما يتطابق مع تعريف 'سياسة' في التعلم التعزيزي كربط احتمالي بين الحالات والأفعال.",
"choice": "C1",
"rewrite": "في كل حالة، يحتفظ النظام بسياسة تحدد التوزيع الاحتمالي الذي يوجه اختيار الأفعال."
}

{
"evidence": "النص يذكر بوضوح استخدام 'شبكة عصبية' تحتوي على 'عدة طبقات مخفية' تقوم بـ 'تعلم تمثيلات معقدة' من البيانات، وهو ما يتطابق مع تعريف 'تعلُّم عميق' الذي يركز على استخدام عدة طبقات مخفية في الشبكات العصبية لحل المشكلات المعقدة وتحديد الخصائص الأساسية للبيانات.",
"choice": "C1",
"rewrite": "يستخدم الحل تقنية تعلُّم عميق، حيث تعتمد على شبكة عصبية تضم عدة طبقات مخفية لتعلم تمثيلات معقدة من البيانات بشكل تدريجي."
}

{
"evidence": "النص يذكر وجود أمثلة مع إجاباتها الصحيحة، ويصف عملية استخدام هذه الأمثلة لتدريب النظام على توقع إجابات أمثلة جديدة. هذا يصف بوضوح آلية 'التعلُّم الموجَّه' حيث تُستخدم بيانات مُسمَّاة (أمثلة مع إجابات) لتدريب النموذج.",
"choice": "C5",
"rewrite": "يُستخدم هذا النوع من التعلم الآلي، والمعروف بالتعلُّم الموجَّه، حيث يتم تدريب النموذج على مجموعة بيانات مُسمَّاة (تتكون من أمثلة مع إجاباتها الصحيحة) لتتمكن من توقع أو تصنيف إجابات أمثلة جديدة."
}

{
"evidence": "النص يذكر بوضوح أن البيانات 'لا تحتوي أي تسميات' وأن الهدف هو 'اكتشاف التجمعات والأنماط'، وهو ما يطابق تعريف 'تعلُّم غير موجَّه' الذي يركز على اكتشاف الأنماط في البيانات غير المسمَّاة.",
"choice": "C3",
"rewrite": "تهدف العملية إلى اكتشاف الأنماط والتجمعات الموجودة في مجموعة بيانات غير مسمَّاة، حيث يقوم النظام باكتشاف هذه الأنماط ذاتيًا دون الحاجة إلى تسميات مسبقة."
}

{
"evidence": "النص يصف عملية حساب الخطأ ثم العودة للخلف عبر طبقات الشبكة لتحديث الأوزان، وهو وصف دقيق لآلية التدرج العكسي (Backpropagation) المستخدمة في تدريب الشبكات العصبية لتقليل الخطأ.",
"choice": "C1",
"rewrite": "بعد حساب الخطأ الناتج عند المخرج، يتم نقل الإشارة عكسيًا عبر طبقات الشبكة لحساب قيمة التدرج اللازمة لتحديث أوزان الشبكة."
}

{
"evidence": "النص يصف أداة قادرة على 'إنشاء نصوص وصور وصوت جديد' بدلاً من مجرد 'تصنيف المحتوى الموجود'. هذا التعريف يطابق تمامًا الخاصية الجوهرية للمصطلح C1 وهو القدرة على إنتاج محتوى جديد (نصوص، صور، أصوات) وليس فقط معالجة أو تصنيف المحتوى الوجودي.",
"choice": "C1",
"rewrite": "تتميز هذه الأداة بقدرتها التوليدية على ابتكار نصوص وصور وأصوات جديدة، بدلاً من الاكتفاء فقط بتصنيف المحتوى الموجود مسبقًا."
}

{
"evidence": "النص يصف عملية تقسيم الجملة إلى وحدات صغيرة لتمكين النظام من تمثيلها ومعالجتها، وهو ما يتطابق مع تعريف 'تقسيم النصوص' كعملية تقسيم النص إلى وحدات لغوية.",
"choice": "C1",
"rewrite": "قبل إدخال الجملة إلى النموذج، يتم تقسيمها إلى وحدات لغوية صغيرة لتتمكن من تمثيلها ومعالجتها."
}

{
"evidence": "النص يتحدث عن تصنيف مراجعات العملاء (نصوص) تلقائيًا لتحديد المشاعر (إيجابي، سلبي، محايد)، وهو ما يتطابق مع تعريف تحليل المشاعر كعملية لتحديد المشاعر والآراء المضمنة في النص.",
"choice": "C2",
"rewrite": "يهدف النظام إلى تصنيف مراجعات العملاء تلقائيًا لتحديد ما إذا كان الرأي المعبّر عنه إيجابيًا أو سلبيًا أو محايدًا."
}

{
"evidence": "النص يصف عملية تحويل جملة من لغة إلى أخرى (العربية إلى الإنجليزية) مع الحفاظ على معناها، وهو ما يتطابق مع تعريف 'ترجمة الآلة' كفرع يهتم بترجمة النص من لغة إلى أخرى.",
"choice": "C1",
"rewrite": "يقوم النظام بتحويل الجملة تلقائيًا من العربية إلى الإنجليزية، مع الحرص على الحفاظ على معناها الأصلية."
}

{
"evidence": "النص يذكر بوضوح وجود 'ملايين السجلات' (كمية كبيرة من البيانات) وهدف البحث هو 'اكتشاف علاقات وأنماط مخفية'، وهو ما يتطابق تمامًا مع تعريف 'تنقيب في البيانات' المتمثل في اكتشاف الأنماط واستخراج المعلومات المفيدة من كميات ضخمة من البيانات.",
"choice": "C1",
"rewrite": "نمتلك ملايين السجلات ونقوم بالبحث فيها لاكتشاف علاقات وأنماط مخفية يمكن استغلالها."
}

{
"evidence": "النص يذكر بوضوح التعامل مع 'بيانات هائلة' تصل 'بسرعة' من 'مصادر متعددة' بأشكال مختلفة، ويؤكد الحاجة إلى 'تقنيات قابلة للتوسع' لتخزين ومعالجة هذه البيانات. هذه الخصائص (الحجم الكبير، السرعة، التنوع، الحاجة للتوسع) تتطابق تمامًا مع تعريف 'بيانات ضخمة' (Big Data) الذي يركز على حجم البيانات الكبير الذي يتطلب تقنيات قابلة للتوسع بسبب خصائص حجمها وتنوعها وسرعتها.",
"choice": "C1",
"rewrite": "نواجه تدفقًا هائلًا للبيانات تصل بسرعة من مصادر متنوعة بأشكال مختلفة، مما يستلزم اعتماد تقنيات قابلة للتوسع لتخزينها ومعالجتها."
}

{
"evidence": "النص يذكر نظامًا يتعامل مع اللغة البشرية، ويفهم النصوص ويستخرج المعنى والمعلومات، وهو ما يتطابق مع تعريف معالجة اللغات الطبيعية كفرع من الذكاء الاصطناعي يهتم بفهم أو توليد اللغة البشرية.",
"choice": "C1",
"rewrite": "يُحتاج إلى نظام معالجة لغوية قادر على التفاعل مع اللغة البشرية، وفهم النصوص واستخراج المعنى والمعلومات منها."
}

{
"evidence": "النص يذكر صراحةً استخدام 'نموذج لغوي' يحتوي على 'عدد هائل من المعاملات' وقد 'دُرّب على كميات كبيرة من النصوص'. هذه الخصائص (عدد كبير من المعاملات وحجم البيانات الضخم للتدريب) تتطابق تمامًا مع تعريف 'المصطلح: نموذج لغوي كبير' الذي يركز على كون النموذج مكوّنًا من عدد كبير من المُعاملات.",
"choice": "C1",
"rewrite": "يُستخدم نموذج لغوي كبير، يتكون من عدد هائل من المعاملات، وقد تم تدريبه على كميات ضخمة من النصوص."
}

{
"evidence": "النص يصف عملية بحث النظام في قاعدة معرفة خارجية قبل الإجابة، ثم استخدام هذه المعلومات في توليد الإجابة. هذا يدمج بين استرجاع معلومات خارجية (قاعدة المعرفة) والنموذج التوليدي (توليد الإجابة) لتحسين جودة الاستجابة، وهو ما يتطابق مع تعريف توليد مُعزَّز بالاسترجاع.",
"choice": "C1",
"rewrite": "قبل أن يقوم النظام بتوليد الإجابة، يقوم باسترجاع المقاطعات ذات الصلة من قاعدة معرفة خارجية، ثم يستخدم هذه المعلومات المدخلة في عملية التوليد لضمان دقة وملاءمة الإجابة للسياق."
}

{
"evidence": "النص يتحدث عن تقليل عدد الخصائص (المتغيرات) مع الحفاظ على أكبر قدر ممكن من المعلومات، وهو ما يتطابق مع جوهر تعريف تحليل المكون الرئيس المتمثل في إزالة التكرار وتقليل الخصائص إلى مكوناتها الرئيسية.",
"choice": "C1",
"rewrite": "نواجه مجموعة من المتغيرات المتداخلة، ونهدف إلى تمثيل البيانات باستخدام عدد أقل من الخصائص مع الحفاظ على أكبر قدر ممكن من المعلومات."
}

{
"evidence": "النص يصف عملية حساب الفرق بين التنبؤات والقيم الحقيقية، ثم رفعه للرباع (نربّع كل فرق)، وأخيراً حساب المتوسط. هذه الخطوات تطابق تماماً تعريف 'متوسط الخطأ التربيعي' (Mean Squared Error) الذي يُحسب بقسمة متوسط الخسارة التربيعية على عدد الأمثلة.",
"choice": "C1",
"rewrite": "يُقيّم التنبؤات بحساب الفرق بينها وبين القيم الحقيقية، ثم يتم رفع كل فرق للرباع وحساب متوسط هذه القيم."
}

{
"evidence": "النص يذكر بوضوح تحليل الصور والفيديو، والتعرف على الأشياء، وفهم المحتوى المرئي، وهي الخصائص الجوهرية لمجال رؤية الحاسب.",
"choice": "C1",
"rewrite": "يقوم النظام بتحليل الصور والفيديوهات باستخدام تقنيات الذكاء الاصطناعي، بهدف التعرف على الأشياء الظاهرة وفهم محتواها المرئي، وهو ما يُعرف بمجال رؤية الحاسب."
}

{
"evidence": "النص يصف قيمة عددية تُحسب لمقارنة مخرجات النموذج بالقيمة المستهدفة بهدف تقليل الفرق، وهو ما يتطابق مع تعريف دالة الخسارة التي تحدد الخطأ بين المخرجات والقيمة المستهدفة.",
"choice": "C2",
"rewrite": "أثناء ضبط النموذج، نحتاج إلى قيمة عددية تعبر عن مقدار اختلاف مخرجاته عن القيمة المستهدفة، وذلك بهدف محاولة تقليل هذا الفرق."
}

{
"evidence": "النص يصف عملية تحديد أسماء الأشخاص والشركات والمدن (أسماء كيانات) وتصنيفها حسب نوعها (فئاتها) داخل الخبر (النص)، وهو ما يطابق تعريف تعرُّف على الكيانات المُسمّاة.",
"choice": "C1",
"rewrite": "يهدف النظام إلى استخراج أسماء الكيانات المذكورة في الخبر، مثل الأشخاص والشركات والمدن، وتصنيف كل اسم ضمن فئته المناسبة."
}

{
"evidence": "النص يصف استخدام شبكة تستخدم مرشحات تتحرك فوق مناطق الصورة لاستخراج الأنماط المرئية، وهو وصف دقيق لآلية عمل الشبكات العصبية الترشيحية (Convolutional Neural Networks) في معالجة الصور.",
"choice": "C1",
"rewrite": "يتم تحليل الصور باستخدام شبكة عصبية ترشيحية، حيث تتحرك مرشحات صغيرة فوق مناطق الصورة لاستخراج الأنماط المرئية بشكل تدريجي."
}

{
"evidence": "النص يذكر 'بيئة منفصلة عن النظام المستخدم فعليًا'، وهو ما يتطابق مع تعريف 'بيئة' في التعلم التعزيزي كعالم يسمح للوكيل برصد حالته، حيث تُستخدم البيئات في هذا السياق لمحاكاة أو عزل العمليات دون التأثير على النظام الحقيقي.",
"choice": "C3",
"rewrite": "نختبر النسخة الجديدة في بيئة معزولة عن النظام المستخدم فعليًا."
}

{
"evidence": "النص يذكر 'الوكيل' في سياق قانوني وتجاري (توقيع عقد بعد التفويض)، بينما تعريف المصطلح C1 يشير إلى كيان برمجي أو مادي يعمل بتحكم ذاتي في بيئته لتحقيق هدف، وهو مفهوم من الذكاء الاصطناعي ولا ينطبق على الوكيل القانوني المذكور في النص.",
"choice": "NONE",
"rewrite": "وقّع الشخص المعني بالشركة على العقد بعد حصوله على التفويض الرسمي."
}

{
"evidence": "النص يذكر 'دورة تدريبية'، وهو ما يتطابق مع تعريف 'تدريب' كعملية تحسين معاملات النموذج باستخدام بيانات، حيث يُستخدم مصطلح 'دورة' في السياق العام للإشارة إلى عملية التدريب الكاملة.",
"choice": "C4",
"rewrite": "حضرت دورة تدريبية استمرت يومين تهدف إلى تحسين معاملات نموذج يعتمد على خوارزمية التعلم الآلي باستخدام مجموعة بيانات مخصصة."
}

{
"evidence": "النص يذكر 'مجموعة من الأمثلة السابقة' التي تم ضبط معاملات الخوارزمية عليها، وهو ما يتطابق مع تعريف 'حُزمة' كمجموعة من الأمثلة المستخدمة لتدريب النموذج.",
"choice": "C1",
"rewrite": "بعد ضبط معاملات الخوارزمية على حُزمة من الأمثلة السابقة، أصبح من الممكن استخدام الناتج المتعلَّم لإجراء تنبؤات على مدخلات جديدة."
}

{
"evidence": "النص يصف كيانًا برمجيًا يقوم بإدراك بيئته (التفاعل مع الأنظمة المحيطة)، ويتخذ قرارات (تحكم ذاتي)، وينفذ مهامًا لتحقيق هدف محدد. هذه الخصائص تتطابق تمامًا مع تعريف 'الوكيل' في المصطلحات المرشحة.",
"choice": "C1",
"rewrite": "ينفّذ الكيان البرمجي مهامًا بشكل مستقل، ويتخذ قرارات ويتفاعل مع الأنظمة المحيطة لتحقيق هدف محدد، مما يجعله يعمل كـ وكيل."
}

{
"evidence": "النص يصف كيانًا مستقلًا يتعلم من خلال التفاعل مع بيئته، ويتغير حالته بناءً على الإجراءات التي يتخذها. هذا التعريف يتطابق مع مفهوم 'الوكيل' (Agent) في التعلم التعزيزي، حيث يُعرّف كيان مادي أو برمجي قادر على إدراك البيئة والعمل بتحكم ذاتي، مع وجود حالة تتغير بعد كل إجراء.",
"choice": "C1",
"rewrite": "يتعلم الوكيل من خلال التفاعل مع بيئته، حيث تتغير حالته بعد كل إجراء يقوم به."
